import sys; sys.path.insert(0,'/home/claude/work/mahimna')
from data import talk,svg
D=dict
F='font-family="Bangers"'
def person(x,y,c='#ff8c1a',skin='#f2c79b',s=1): return f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2.5"><circle cy="-30" r="12" fill="{skin}"/><path d="M-18 20 q18 -50 36 0z" fill="{c}"/></g>'
V=[
D(lines=['bhaja govindaṃ bhaja govindaṃ','govindaṃ bhaja mūḍhamate |','samprāpte sannihite kāle','nahi nahi rakṣati ḍukṛñkaraṇe ‖1‖'],
 theme='WORSHIP GOVINDA, O FOOLISH MIND',
 svg=svg('An old scholar poring over a grammar book while an hourglass runs out, and Govinda with a flute shown above',
  person(70,120,'#999','#e0c09b')+'<rect x="44" y="118" width="54" height="30" fill="#fff3b0" stroke="#111" stroke-width="2"/><text x="71" y="138" text-anchor="middle" font-family="Noto Sans" font-style="italic" font-size="9">ḍukṛñ karaṇe</text>'
  '<path d="M160 40 h30 l-15 30 l15 30 h-30 l15 -30z" fill="#fff" stroke="#111" stroke-width="2"/><path d="M168 96 h14 l-7 -10z" fill="#e0a800"/><text x="175" y="120" text-anchor="middle" '+F+' font-size="10">TIME RUNS OUT</text>'
  '<text x="110" y="24" text-anchor="middle" '+F+' font-size="13" fill="#1d6fb8">BHAJA GOVINDAM!</text>','#e3f2fd'),
 mean='Worship Govinda, worship Govinda, worship Govinda, O foolish mind! When the appointed time of death draws near, the grammar rule "ḍukṛñ karaṇe" will not save you, no, not at all.',
 plain='Turn to God. When death comes, the grammar you memorised, the learning you collected, will not save you.',
 words=[('bhaja','<b>worship</b>, seek, turn to'),('govinda','<b>Govinda</b>: Kṛṣṇa, Viṣṇu, "finder of the cows", "known through the Vedas"'),('mūḍhamate','<b>O deluded mind</b>, O fool'),('samprāpte sannihite kāle','<b>when the appointed time has come near</b>'),('nahi nahi rakṣati','<b>does not, does not save</b>'),('ḍukṛñ karaṇe','a grammar rule: "the root kṛ, in the sense of doing"')],
 deep='<p><b>The refrain.</b> This verse is the chorus of the whole hymn. In singing, it is repeated after every verse, so the listener hears "bhaja govindaṃ" again and again.</p><p><b>Ḍukṛñ karaṇe.</b> A line from Pāṇini\'s list of verb roots: "the root ḍukṛñ (kṛ), in the sense of doing". The old man in the story was cramming exactly this. Śaṅkara uses it to stand for all learning that is only memorised, never lived.</p><p><b>Mūḍhamate.</b> "O fool": a harsh word, but tender too. Śaṅkara is speaking to the mind, ours and the old man\'s, the way a teacher shakes a student awake.</p><p><b>Govinda.</b> A name of Kṛṣṇa: "the one who finds and tends the cows", also read as "the one known through the Vedas (go)".</p>',
 cards=('💡 Pāṇini','The great grammarian of Sanskrit, whose rules and root lists the old man was learning.','💡 Moha Mudgara','The hymn\'s older name: "the hammer that breaks delusion".'),
 inner='Knowledge you only memorise is a load to carry. Knowledge you live is a boat to cross with.',
 talk=('Is Śaṅkara against learning grammar?','Not at all: he was a great scholar himself. He\'s against spending your last years on rules while forgetting what life is for.'),
 key='When the time comes, <b>no grammar rule will save you; turn to Govinda</b>.'),
D(lines=['mūḍha jahīhi dhanāgamatṛṣṇāṃ','kuru sadbuddhiṃ manasi vitṛṣṇām |','yallabhase nijakarmopāttaṃ','vittaṃ tena vinodaya cittam ‖2‖'],
 theme='ENOUGH IS A FEAST',
 svg=svg('A person turning away from a growing pile of coins to sit contentedly with a small bowl',
  ''.join(f'<circle cx="{40+(k%4)*12}" cy="{140-(k//4)*10}" r="6" fill="#ffd60a" stroke="#111" stroke-width="1.5"/>' for k in range(14))+person(150,118,'#1d6fb8')+'<path d="M130 132 q20 10 40 0" fill="#c9a26b" stroke="#111" stroke-width="2"/><text x="60" y="40" text-anchor="middle" '+F+' font-size="11" fill="#c0392b">MORE! MORE!</text><text x="150" y="40" text-anchor="middle" '+F+' font-size="11" fill="#2a9d6f">ENOUGH.</text>','#e3f2fd'),
 mean='O fool, give up the thirst to pile up wealth. Make your mind good and free of craving. Whatever you gain by your own work, let that content your mind.',
 plain='Stop chasing more money. Earn honestly, and be happy with what your own effort brings.',
 words=[('jahīhi','<b>give up</b>'),('dhana-āgama-tṛṣṇā','<b>thirst for getting wealth</b>'),('sad-buddhi','<b>good understanding</b>'),('vitṛṣṇā','<b>free from craving</b>'),('nija-karma-upāttam','<b>earned by your own work</b>'),('vinodaya cittam','<b>delight your mind</b>, be content')],
 deep='<p><b>Not "don\'t earn".</b> Śaṅkara doesn\'t tell the householder to stop working. He says: earn by your own effort (<i>nija-karma</i>), and let that be enough. The poison is the <i>tṛṣṇā</i>, the thirst that grows with every coin.</p><p><b>Thirst.</b> <i>Tṛṣṇā</i> is literally thirst: drinking salt water makes it worse. So with wealth chased for its own sake.</p><p><b>Contentment.</b> <i>Santoṣa</i>, contentment, is one of the niyamas of yoga. The mind that is content is free to think of higher things.</p>',
 cards=('💡 Tṛṣṇā','"Thirst": craving, which the Buddha also named as the root of suffering.','💡 Santoṣa','Contentment: one of the five niyamas in Patañjali\'s Yoga Sūtras.'),
 inner='Work hard, earn honestly, then stop counting. Contentment is the only wealth that never runs out.',
 talk=('So is money bad?','Earning is fine, says Śaṅkara. It\'s the endless thirst for more that robs your peace.'),
 key='Earn honestly, <b>and let it be enough</b>.'),
D(lines=['nārīstanabharanābhīdeśaṃ','dṛṣṭvā mā gā mohāveśam |','etanmāṃsavasādivikāraṃ','manasi vicintaya vāraṃ vāram ‖3‖'],
 theme='THE BODY IS NOT THE PERSON',
 svg=svg('A mirror showing a figure, and beside it a simple outline of a skeleton and a glowing light within, showing the self beyond the body',
  '<rect x="30" y="30" width="70" height="110" rx="35" fill="#dcecff" stroke="#111" stroke-width="2.5"/>'+person(65,110,'#e05a8a')+'<g stroke="#111" stroke-width="2" fill="none"><circle cx="160" cy="54" r="12"/><path d="M160 66 v40 M146 76 h28 M150 86 h20 M150 96 h20 M160 106 l-12 30 M160 106 l12 30"/></g><circle cx="160" cy="90" r="6" fill="#ffd60a"/><text x="110" y="22" text-anchor="middle" '+F+' font-size="11">LOOK DEEPER</text>','#e3f2fd'),
 mean='Seeing the beauty of a woman\'s body, do not fall into infatuation. Reflect in your mind again and again: this is only a changing form of flesh, fat and the like.',
 plain='Don\'t be swept away by attraction to a body. Remind yourself that the body is only flesh; the person, the Self, is something else.',
 words=[('nārī','a <b>woman</b>'),('deśa','a <b>part, region</b> (of the body)'),('mā gāḥ moha-āveśam','<b>do not fall into infatuation</b>'),('māṃsa-vasā','<b>flesh and fat</b>'),('vikāra','<b>a modification</b>, changing form'),('vāraṃ vāram','<b>again and again</b>')],
 deep='<p><b>Who is it for?</b> Śaṅkara was a monk, speaking to monks and seekers in a society where the seekers were mostly men. The point is not about women; it is about any body, including one\'s own. Infatuation mistakes the outer form for the person.</p><p><b>Vikāra.</b> A "modification": the body is food turned into flesh, always changing, always ageing. The Self that looks through the eyes does not change.</p><p><b>Not hatred.</b> Vedānta does not ask us to despise the body, only to see it clearly. A body is a house, not the one who lives in it.</p>',
 cards=('💡 Moha','Delusion, infatuation: the "moha" that the Moha Mudgara hammers.','💡 Deha and dehī','The body and the one who has the body: a key Gītā distinction.'),
 inner='Love the person, not the packaging. The packaging changes; the one inside does not.',
 talk=('Isn\'t this verse a bit harsh?','It was said to monks in Śaṅkara\'s time. Its real point is for all of us: don\'t mistake a body, anyone\'s, for the person.'),
 key='The body is a changing form; <b>the Self within is what is real</b>.',
 note='Some modern editions adapt this verse for all readers; we keep the traditional text and read it as a teaching on bodily attachment in general.'),
D(lines=['nalinīdalagatajalamatitaralaṃ','tadvajjīvitamatiśayacapalam |','viddhi vyādhyabhimānagrastaṃ','lokaṃ śokahataṃ ca samastam ‖4‖'],
 theme='A DROP ON A LOTUS LEAF',
 svg=svg('A trembling drop of water on a lotus leaf, about to roll off',
  '<ellipse cx="110" cy="110" rx="90" ry="30" fill="#2a9d6f" stroke="#111" stroke-width="2.5"/><path d="M110 110 L110 80" stroke="#1b6b4b" stroke-width="2"/><circle cx="130" cy="96" r="12" fill="#bfe6ff" stroke="#111" stroke-width="2"/><circle cx="126" cy="92" r="3" fill="#fff"/><path d="M148 92 q8 4 12 0 M150 100 q8 4 12 0" fill="none" stroke="#111" stroke-width="1.5"/><text x="110" y="30" text-anchor="middle" '+F+' font-size="12" fill="#1d6fb8">LIFE IS LIKE THIS DROP</text>','#e3f2fd'),
 mean='Water on a lotus leaf is very unsteady; just so, life is extremely fleeting. Know that the whole world is seized by disease and pride, and struck by sorrow.',
 plain='Life is as unstable as a water drop on a lotus leaf. The world is full of illness, ego and grief. Know this, and turn to what lasts.',
 words=[('nalinī-dala','a <b>lotus leaf</b>'),('gata-jalam','<b>water resting on it</b>'),('atitaralam','<b>very unsteady</b>'),('jīvitam','<b>life</b>'),('vyādhi-abhimāna','<b>disease and pride</b>'),('śoka-hatam','<b>struck by sorrow</b>')],
 deep='<p><b>The image.</b> A drop of water on a lotus leaf never soaks in. It trembles, rolls, and at the slightest breeze is gone. That is life: bright, beautiful and uncertain.</p><p><b>Another lesson in the same image.</b> The Gītā (5.10) uses the lotus leaf differently: the wise act in the world untouched by it, like a lotus leaf by water. The leaf teaches both fragility and freedom.</p><p><b>Not gloom.</b> Seeing how fleeting life is isn\'t meant to depress us; it is meant to wake us, so we don\'t waste the time we have.</p>',
 cards=('💡 Padmapatram','"Like a lotus leaf in water": Gītā 5.10, acting without being stained.','💡 Abhimāna','Pride, ego: listed with disease as what grips the world.'),
 inner='Because the drop may fall any moment, make this moment count.',
 talk=('That\'s a sad picture.','It\'s a true one, and a beautiful one. A drop on a lotus shines. Life is like that: brief, so live it well.'),
 key='Life trembles like a drop on a lotus leaf: <b>don\'t waste it</b>.'),
D(lines=['yāvadvittopārjanasaktaḥ','tāvannijaparivāro raktaḥ |','paścājjīvati jarjaradehe','vārtāṃ ko\'pi na pṛcchati gehe ‖5‖'],
 theme='WHILE YOU EARN',
 svg=svg('Two scenes: a working man surrounded by smiling family; the same man old and alone in a corner while others look away',
  person(50,120,'#1d6fb8')+person(26,124,'#e05a8a','#f2c79b',.7)+person(76,124,'#2a9d6f','#f2c79b',.7)+'<text x="50" y="30" text-anchor="middle" '+F+' font-size="10">EARNING</text><path d="M110 20 v130" stroke="#111" stroke-dasharray="4 4"/>'+person(170,124,'#999','#e0c09b')+'<text x="170" y="30" text-anchor="middle" '+F+' font-size="10">OLD AGE</text>','#e3f2fd'),
 mean='As long as a man is busy earning money, so long his family is attached to him. Later, when he lives on in a worn-out body, no one at home even asks him a word.',
 plain='While you earn, your family crowds around. When you\'re old and frail, few even talk to you.',
 words=[('yāvat · tāvat','<b>as long as</b> · <b>so long</b>'),('vitta-upārjana','<b>earning wealth</b>'),('nija-parivāraḥ','<b>one\'s own family</b>'),('raktaḥ','<b>attached</b>, devoted'),('jarjara-deha','<b>a worn-out body</b>'),('vārtām','<b>a word</b>, news')],
 deep='<p><b>A hard truth.</b> Śaṅkara is not attacking families; he is warning against putting all our hope in what is temporary. Love that depends on usefulness fades when the usefulness does.</p><p><b>Then what?</b> If even family attention depends on what we can give, then lasting security has to come from within, from our relationship with the Lord and the Self.</p><p><b>For us as children.</b> The verse also quietly asks us: do we ask after our own elders?</p>',
 cards=('💡 Parivāra','Family, household: here those who gather round a provider.','💡 Gṛhastha','The householder stage of life: earning, raising family; honoured, but not the final goal.'),
 inner='Build a life that does not depend on being useful to others. And make sure the elders in your home are never left without a kind word.',
 talk=('Is this really true of families?','Not of every family. But Śaṅkara is warning: don\'t rest your whole peace on others\' attention. Find it in God and in yourself.'),
 key='Love that depends on your earnings <b>fades with them; seek what lasts</b>.'),
D(lines=['yāvatpavano nivasati dehe','tāvatpṛcchati kuśalaṃ gehe |','gatavati vāyau dehāpāye','bhāryā bibhyati tasminkāye ‖6‖'],
 theme='WHEN THE BREATH LEAVES',
 svg=svg('A lamp with its flame blowing away as the breath leaves a body under a white cloth, with family stepping back',
  '<rect x="40" y="110" width="120" height="20" rx="4" fill="#fff" stroke="#111" stroke-width="2.5"/><path d="M40 110 q60 -16 120 0" fill="#fff" stroke="#111" stroke-width="2"/><path d="M170 120 h20 l-3 8 h-14z" fill="#e0a800" stroke="#111" stroke-width="1.5"/><path d="M180 120 q-10 -18 14 -30" fill="none" stroke="#bbb" stroke-width="3"/>'
  '<text x="110" y="40" text-anchor="middle" '+F+' font-size="11">THE BREATH DEPARTS</text>','#e3f2fd'),
 mean='As long as breath dwells in the body, people at home ask after your welfare. When the breath has gone and the body has fallen, even your wife is afraid of that same body.',
 plain='While you breathe, everyone asks how you are. When the breath leaves, even your closest fear your body.',
 words=[('pavanaḥ · vāyuḥ','<b>breath</b>, life-air'),('nivasati dehe','<b>dwells in the body</b>'),('kuśalam','<b>welfare</b>, how one is'),('gatavati vāyau','<b>when the breath has gone</b>'),('dehāpāye','<b>when the body falls</b>'),('bibhyati','<b>is afraid</b>')],
 deep='<p><b>Who were they asking after?</b> The family loved the person, not the body. When the breath leaves, the body that was so dear becomes something to fear and to cremate. So, Śaṅkara asks, which was the real you?</p><p><b>Prāṇa.</b> The breath, <i>prāṇa</i>, is the sign of life. Its leaving shows that the body was never the self: something left, and that something was what everyone loved.</p><p><b>A pointer to the Self.</b> These verses (5 and 6) are not cynical; they push us to ask: what am I, really?</p>',
 cards=('💡 Prāṇa','The life-breath: in Vedānta, the vital force that animates the body.','💡 Antyeṣṭi','The last rites, performed soon after death: the body is returned to the elements.'),
 inner='What everyone loved in you was never the body. Find out what it was.',
 talk=('Even the wife is afraid?','Of the lifeless body, yes. It shows what she really loved was the person, the life inside. Śaṅkara wants us to find that inner life.'),
 key='When the breath leaves, the body is feared: <b>so what were we, really?</b>'),
D(lines=['bālastāvatkrīḍāsaktaḥ','taruṇastāvattaruṇīsaktaḥ |','vṛddhastāvaccintāsaktaḥ','parame brahmaṇi ko\'pi na saktaḥ ‖7‖'],
 theme='CHILD, YOUTH, OLD MAN',
 svg=svg('Three stages of life: a child with a ball, a young man looking at a sweetheart, an old man worrying; and an empty seat facing a glowing light',
  person(30,120,'#ffd60a','#f2c79b',.7)+'<circle cx="46" cy="134" r="5" fill="#e63946" stroke="#111"/>'+person(80,118,'#1d6fb8')+person(104,122,'#e05a8a','#f2c79b',.8)+person(150,120,'#999','#e0c09b')+'<text x="150" y="70" text-anchor="middle" '+F+' font-size="16" fill="#c0392b">?!</text><circle cx="196" cy="40" r="12" fill="#ffd60a"/><text x="196" y="66" text-anchor="middle" '+F+' font-size="8">BRAHMAN</text>','#e3f2fd'),
 mean='The child is absorbed in play; the young man is absorbed in a young woman; the old man is absorbed in worries. But in the supreme Brahman, no one is absorbed at all.',
 plain='As children we play, as youths we chase love, as elders we worry. At no stage do we give our minds to the highest.',
 words=[('bālaḥ','the <b>child</b>'),('krīḍā-saktaḥ','<b>attached to play</b>'),('taruṇaḥ','the <b>young man</b>'),('vṛddhaḥ','the <b>old man</b>'),('cintā','<b>worry, anxiety</b>'),('parame brahmaṇi','<b>in the supreme Brahman</b>')],
 deep='<p><b>A whole life in four lines.</b> Childhood goes in play, youth in love, old age in worry. Each stage has its own attachment, and each is natural. The problem is that there is never a stage when we turn to the highest.</p><p><b>Saktaḥ.</b> The same word ends each line: "attached". Śaṅkara shows that attachment simply changes its object as we age.</p><p><b>The fourth line.</b> If attachment is our nature, he hints, attach it to the right thing: <i>parame brahmaṇi</i>, the supreme reality.</p>',
 cards=('💡 Āśramas','The four stages of life: student, householder, forest-dweller, renunciate.','💡 Brahman','The supreme reality in Vedānta: being, consciousness, bliss.'),
 inner='Don\'t wait for "later" to seek the highest. Every stage of life has its own excuse.',
 talk=('So when should we think of God?','Śaṅkara\'s answer: now. Childhood plays, youth loves, age worries. If we wait for a free stage, it never comes.'),
 key='Play, love, worry: <b>every age has its attachment, none chooses the highest</b>.'),
D(lines=['kā te kāntā kaste putraḥ','saṃsāro\'yamatīva vicitraḥ |','kasya tvaṃ kaḥ kuta āyātas','tattvaṃ cintaya tadiha bhrātaḥ ‖8‖'],
 theme='WHO ARE YOU, REALLY?',
 svg=svg('A person standing on a crossroads looking at a question mark in the sky, with small figures of family around',
  person(110,120,'#1d6fb8')+person(60,128,'#e05a8a','#f2c79b',.7)+person(160,128,'#2a9d6f','#f2c79b',.6)+'<text x="110" y="50" text-anchor="middle" '+F+' font-size="40" fill="#1d6fb8">?</text><text x="110" y="152" text-anchor="middle" '+F+' font-size="10">WHENCE? WHOSE? WHO?</text>','#e3f2fd'),
 mean='Who is your wife? Who is your son? This world of saṃsāra is very strange. Whose are you? Who are you? Where have you come from? Think on that truth, here and now, O brother.',
 plain='Who are your family, really? Who are you? Where did you come from? This world is very strange. Brother, think about it now.',
 words=[('kāntā','<b>beloved</b>, wife'),('putraḥ','<b>son</b>'),('saṃsāraḥ','<b>the round of worldly life</b>'),('vicitraḥ','<b>strange</b>, wonderful'),('kuta āyātaḥ','<b>from where have you come?</b>'),('bhrātaḥ','<b>O brother</b>')],
 deep='<p><b>The great questions.</b> This is the heart of Vedānta in two lines: <i>kas tvam</i>, "who are you?"; <i>kuta āyātaḥ</i>, "where have you come from?" Śaṅkara\'s whole philosophy is an answer: you are not this body or these roles; you are the Self.</p><p><b>Brother.</b> After calling us "fool" in verse 1, here he calls us <i>bhrātaḥ</i>, "brother". The teacher is gentle again.</p><p><b>Not unloving.</b> Asking "who is your son?" is not a rejection of family; it is a reminder that every relationship is a meeting on a journey, not the end of the journey.</p>',
 cards=('💡 Ko\'ham','"Who am I?": the question Ramaṇa Maharṣi made the centre of his teaching.','💡 Saṃsāra','The flowing round of birth, death and rebirth.'),
 inner='Every relationship is a meeting of travellers. Love them on the road, and remember where the road leads.',
 talk=('Who am I, then?','That\'s exactly the question Śaṅkara wants us to sit with. His answer, across his whole work: not the body, not the mind, but the Self.'),
 key='"Who are you? Where did you come from?" <b>Think on it now, brother</b>.'),
D(lines=['satsaṅgatve nissaṅgatvaṃ','nissaṅgatve nirmohatvam |','nirmohatve niścalatattvaṃ','niścalatattve jīvanmuktiḥ ‖9‖'],
 theme='THE LADDER OF GOOD COMPANY',
 svg=svg('A four-step ladder: good company, detachment, freedom from delusion, steady truth, leading to liberation shown as a sunrise',
  ''.join(f'<rect x="{20+44*k}" y="{120-26*k}" width="44" height="{26*(k+1)+14}" fill="{c}" stroke="#111" stroke-width="2"/><text x="{42+44*k}" y="{134-26*k}" text-anchor="middle" {F} font-size="7">{t}</text>' for k,(c,t) in enumerate([('#dcecff','SATSAṄGA'),('#c7e1ff','DETACH'),('#a9d1ff','NO MOHA'),('#8cc2ff','STEADY')]))
  +'<circle cx="200" cy="30" r="14" fill="#ffd60a" stroke="#111" stroke-width="2"/><text x="190" y="62" text-anchor="middle" '+F+' font-size="8">FREEDOM</text>','#e3f2fd'),
 mean='From good company comes non-attachment; from non-attachment, freedom from delusion; from freedom from delusion, steadiness in the truth; from steadiness in the truth, liberation while still living.',
 plain='Keep good company, and you slowly let go. Letting go clears delusion; a clear mind settles in the truth; and that is freedom, here and now.',
 words=[('satsaṅga','<b>good company</b>, company of the wise'),('nissaṅgatva','<b>non-attachment</b>'),('nirmohatva','<b>freedom from delusion</b>'),('niścala-tattva','<b>unshakable truth</b>, steadiness in reality'),('jīvanmukti','<b>liberation while living</b>'),('-tve','"<b>in</b>" / "<b>from</b>": each step leads to the next')],
 deep='<p><b>A chain reaction.</b> The most quoted verse of the hymn is a ladder. Each rung rests on the one below: satsaṅga, then detachment, then clarity, then steadiness, then freedom.</p><p><b>Why company first?</b> We become like those we spend time with. Being near the wise, good books and devotional singing slowly changes what we want.</p><p><b>Jīvanmukti.</b> Liberation is not only after death. Śaṅkara\'s Vedānta speaks of the <i>jīvanmukta</i>, one who is free while still living in the body.</p>',
 cards=('💡 Satsaṅga','"Company of truth": gatherings for hearing scripture and singing bhajans take this name.','💡 Jīvanmukta','One liberated while alive; the Gītā\'s "sthitaprajña" is a close picture.'),
 inner='Choose your company carefully: it is the first rung of the ladder to freedom.',
 talk=('Freedom starts with friends?','With good company. Spend time with the wise and the good, and the rest follows step by step.'),
 key='Good company → detachment → clarity → steadiness → <b>freedom, here and now</b>.'),
D(lines=['vayasi gate kaḥ kāmavikāraḥ','śuṣke nīre kaḥ kāsāraḥ |','kṣīṇe vitte kaḥ parivāraḥ','jñāte tattve kaḥ saṃsāraḥ ‖10‖'],
 theme='WHEN THE WATER DRIES UP',
 svg=svg('A dried, cracked lake bed with no water, and a person who has seen the truth smiling under a sunrise',
  '<ellipse cx="80" cy="120" rx="64" ry="20" fill="#d9c79a" stroke="#111" stroke-width="2.5"/><path d="M40 118 l14 6 l10 -8 l16 8 l12 -6 l14 6" fill="none" stroke="#8a6a3a" stroke-width="2"/><text x="80" y="90" text-anchor="middle" '+F+' font-size="10">NO WATER, NO LAKE</text>'+person(170,120,'#1d6fb8')+'<circle cx="170" cy="40" r="14" fill="#ffd60a" stroke="#111" stroke-width="2"/>','#e3f2fd'),
 mean='When youth has gone, where is lust? When the water has dried, where is the lake? When wealth is spent, where is the family circle? When the truth is known, where is saṃsāra?',
 plain='No youth, no lust; no water, no lake; no money, no crowd of relatives. And when you know the truth, the whole round of worldly bondage simply disappears.',
 words=[('vayasi gate','<b>when youth has gone</b>'),('kāma-vikāraḥ','<b>the stirring of desire</b>'),('śuṣke nīre','<b>when the water has dried</b>'),('kāsāraḥ','a <b>lake</b>'),('kṣīṇe vitte','<b>when wealth is spent</b>'),('jñāte tattve','<b>when the truth is known</b>')],
 deep='<p><b>Three and then one.</b> The first three lines are things everyone sees: things depend on their causes and vanish when the causes go. The fourth line uses the same logic for the deepest point: saṃsāra depends on ignorance; when the truth is known, it is gone.</p><p><b>A teacher\'s method.</b> Śaṅkara moves from the obvious to the profound: if you accept the first three, you have to accept the fourth.</p><p><b>End of Part 1.</b> The first ten verses have shaken us awake about wealth, the body, life\'s shortness and family. Part 2 continues the hammering of delusion.</p>',
 cards=('💡 Kārya and kāraṇa','Effect and cause: when the cause goes, the effect goes.','💡 Ajñāna','Ignorance: in Advaita, the cause of saṃsāra, removed by knowledge.'),
 inner='Bondage has a cause. Remove the cause, ignorance, and bondage dries up like a lake without water.',
 talk=('Saṃsāra just disappears?','When the truth is known, says Śaṅkara. Like a lake without water, it can\'t continue without its cause.'),
 key='No water, no lake; <b>no ignorance, no bondage</b>.'),
]
